'use client';
import {useEffect,useRef,useState} from 'react';
import SocialLinks from './SocialLinks';
import {ArrowUpRight,Plus,Minus,Search,MapPin,Mail,Wine,Coffee,GlassWater,Phone,ChevronDown} from 'lucide-react';
import {drinkMenu,money,normalize,type Dish} from './menu';
import {drinkCategories} from './drinks';
import {business,eventOffers,openingState,originalMenus,type EventOffer,type OriginalKind} from './official';

export function OpeningHours(){
 const [state,setState]=useState<ReturnType<typeof openingState>|null>(null);
 useEffect(()=>{const refresh=()=>setState(openingState(new Date()));refresh();const timer=setInterval(refresh,60000);return()=>clearInterval(timer);},[]);
 return <><div className={'opening-status '+(state?.open?'is-open':'')}>{state?<><i/>{state.open?'Deschis acum · până la '+state.closing:'Închis acum · deschidem la 10:00'}</>:'Program restaurant'}</div><dl className="hours-list">{business.hours.map(h=><div key={h.days}><dt>{h.days}</dt><dd>{h.hours}</dd></div>)}</dl></>;
}
export function VisitDetails(){return <div className="visit-details"><div className="visit-address"><MapPin size={28}/><p className="eyebrow dark">NE VEDEM ÎN BRAGADIRU</p><h3>Un loc pentru<br/>momentele tale.</h3><address>{business.address}</address><a className="button dark-button" href={business.directions} target="_blank" rel="noreferrer">Pornește navigarea <ArrowUpRight size={18}/></a><a className="contact-email" href={'mailto:'+business.email}><Mail size={18}/>{business.email}</a><SocialLinks className="visit-socials"/></div><iframe className="location-map" title="Locația Casa Mia by OAna · Strada Safirului 69R, Bragadiru" src="https://maps.google.com/maps?q=Strada%20Safirului%2069R%2C%20Bragadiru%2C%20Ilfov&z=17&output=embed" loading="lazy" referrerPolicy="no-referrer-when-downgrade" allowFullScreen/></div>}
export function BeverageVisual({dish}:{dish:Dish}){const Icon=dish.category==='Cafea & ceai'?Coffee: ['Răcoritoare','Fresh & limonadă','Cocktailuri fără alcool'].includes(dish.category)?GlassWater:Wine;return <div className="beverage-visual"><Icon size={52} strokeWidth={1}/><span>{dish.category}</span>{dish.weight&&<strong>{dish.weight}</strong>}</div>}
export function DrinksMenu({onOriginal,onChoose,onAdd,cart,onChange}:{onOriginal:()=>void;onChoose:(d:Dish)=>void;onAdd:(d:Dish)=>void;cart:Record<string,number>;onChange:(id:string,delta:number)=>void}){
 const [category,setCategory]=useState('Toate băuturile');const [query,setQuery]=useState('');
 const filtered=drinkMenu.filter(d=>(category==='Toate băuturile'||d.category===category)&&normalize(d.name+' '+d.ingredients+' '+d.category).includes(normalize(query)));
 const groups=drinkCategories.filter(c=>filtered.some(d=>d.category===c));
 return <div className="drinks-content"><div className="wrap"><div className="bar-intro"><div><p className="eyebrow dark">DE LA PRIMUL ESPRESSO LA ULTIMUL TOAST</p><p>Cafea, limonade, cocktailuri și vinuri. Alege ceva pe gustul tău.</p></div><button className="underlink" onClick={onOriginal}>Meniul bar în original <ArrowUpRight size={17}/></button></div><label className="search drinks-search"><Search size={19}/><input aria-label="Caută în meniul de băuturi" placeholder="Caută o băutură…" value={query} onChange={e=>setQuery(e.target.value)}/></label></div><div className="category-bar"><div className="wrap categories" role="group" aria-label="Categorii băuturi">{['Toate băuturile',...drinkCategories].map(c=><button key={c} aria-pressed={category===c} className={category===c?'active':''} onClick={()=>{setCategory(c);setQuery('')}}>{c}</button>)}</div></div><div className="wrap"><div className="menu-heading"><h3>{query?'Rezultatele căutării':category}</h3><span>{filtered.length} băuturi</span></div>{!filtered.length?<div className="empty"><Wine size={32}/><p>Nu am găsit băutura căutată.</p><button className="underlink" onClick={()=>{setQuery('');setCategory('Toate băuturile')}}>Vezi toate băuturile</button></div>:<div className="drinks-groups">{groups.map(c=><section className="drink-group" key={c}><h3>{c}</h3><div>{filtered.filter(d=>d.category===c).map(d=><article className="drink-row" key={d.id}><button className="drink-description" onClick={()=>onChoose(d)}><span>{d.name}</span>{d.weight&&<small>{d.weight}</small>}{d.ingredients&&<p>{d.ingredients}</p>}</button><strong>{money(d.price)}</strong>{cart[d.id]?<div className="quantity compact"><button aria-label={'Scade '+d.name} onClick={()=>onChange(d.id,-1)}><Minus size={13}/></button><span>{cart[d.id]}</span><button aria-label={'Adaugă '+d.name} onClick={()=>onChange(d.id,1)}><Plus size={13}/></button></div>:<button className="add-button" aria-label={'Adaugă '+d.name} onClick={()=>onAdd(d)}><Plus size={16}/></button>}</article>)}</div></section>)}</div>}<p className="menu-footnotes">Prețurile și cantitățile sunt preluate din meniul bar publicat de Casa Mia by OAna. Acolo unde nu este precizată cantitatea, aceasta nu este completată estimativ.</p></div></div>;
}
export function OriginalMenuGallery({kind,onChange}:{kind:OriginalKind;onChange:(kind:OriginalKind)=>void}){const m=originalMenus[kind];return <div className="panel-body"><p className="eyebrow dark">MENIURILE CASA MIA, ÎN ORIGINAL</p><h2>{m.title}.</h2><p>Deschide o pagină pentru a o vedea la rezoluția originală sau pentru a o descărca.</p><div className="original-menu-tabs">{Object.entries(originalMenus).map(([key,m])=><button key={key} onClick={()=>onChange(key as OriginalKind)} className={kind===key?'active':''} aria-pressed={kind===key}>{m.title}</button>)}</div><div className={'menu-original digital-original '+(m.images.length===1?'single':'')}>{m.images.map((src,i)=><a href={'./menus/'+src} target="_blank" rel="noreferrer" key={src}><img src={'./menus/'+src} alt={m.title+' · pagina '+(i+1)} loading="lazy"/><span>Deschide pagina {i+1} <ArrowUpRight size={16}/></span></a>)}</div></div>}
export function EventMenus({onOriginal,initialOccasion='cununie',compact=false}:{onOriginal:(kind:OriginalKind)=>void;initialOccasion?:'cununie'|'botez'|'parastas';compact?:boolean}){
 const [occasion,setOccasion]=useState<'cununie'|'botez'|'parastas'>(initialOccasion);const group=occasion==='parastas'?'parastas':'celebration';const [quote,setQuote]=useState<EventOffer|null>(null);const quoteRef=useRef<HTMLDivElement>(null);
 function request(o:EventOffer){setQuote(group==='celebration'?{...o,title:occasion==='cununie'?'Cununie':'Botez'}:o);setTimeout(()=>{quoteRef.current?.scrollIntoView({behavior:'smooth',block:'center'});quoteRef.current?.querySelector<HTMLInputElement>('input')?.focus({preventScroll:true});},50)}
 function draft(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(!quote)return;const f=new FormData(e.currentTarget);const body=['Bună ziua,','Doresc o ofertă pentru '+quote.title+' – '+quote.subtitle+'.','Nume: '+f.get('name'),'Telefon: '+f.get('phone'),'Data: '+f.get('date'),'Număr invitați: '+f.get('guests'),'Observații: '+(f.get('notes')||'')].join('\n');window.location.href='mailto:'+business.email+'?subject='+encodeURIComponent('Solicitare ofertă · '+(group==='celebration'?occasion:quote.title)+' · '+quote.subtitle)+'&body='+encodeURIComponent(body)}
 return <div className={'event-menus wrap '+(compact?'event-menus-compact':'')} id={compact?undefined:'oferte-evenimente'}><div className="section-head"><div><p className="eyebrow">OFERTELE CASA MIA</p><h2>{compact?<>Meniuri pentru <em>{occasion}.</em></>:<>Un meniu pentru<br/><em>ocazia ta.</em></>}</h2></div><div className="event-menu-switch" role="group" aria-label="Tip eveniment">{(['cununie','botez','parastas'] as const).map(kind=><button key={kind} aria-pressed={occasion===kind} className={occasion===kind?'active':''} onClick={()=>{setOccasion(kind);setQuote(null)}}>{kind==='cununie'?'Cununie':kind==='botez'?'Botez':'Parastas'}</button>)}</div></div><div className="event-offer-grid">{eventOffers.filter(o=>group==='celebration'?o.id!=='parastas':o.id==='parastas').map(o=><article className="event-offer" key={occasion+o.subtitle}><p className="eyebrow dark">{group==='parastas'?o.title:occasion==='cununie'?'Cununie':'Botez'}</p><h3>{o.subtitle}</h3>{o.price?<div className="event-offer-price"><strong>{o.price} €</strong><span>/ persoană</span></div>:<div className="parastas-price-preview">{o.sections.filter(s=>s.price!==undefined).map(s=><span key={s.title}>{s.title}<strong>{s.price} lei / persoană</strong></span>)}{o.subtitle.includes('post')&&<span>Fel principal<strong>35 / 40 lei / persoană</strong></span>}</div>}{o.service&&<p className="event-service">+{o.service}% servicii pentru fiecare meniu agreat</p>}{o.price&&<div className="event-includes"><span>Aranjamente masă</span><span>Meniu mâncare</span><span>Open bar · max. 6 ore</span></div>}<details className="offer-details"><summary>Vezi meniul complet <ChevronDown size={18}/></summary>{o.sections.map(s=><div className="offer-course" key={s.title}><h4>{s.title}{s.price!==undefined&&<strong>{s.price} RON / persoană</strong>}</h4><ul>{s.items.map(item=><li key={item}>{item}</li>)}</ul>{s.note&&<p className="course-note">{s.note}</p>}</div>)}{o.extras&&<div className="offer-course"><h4>Opțiuni suplimentare</h4><ul>{o.extras.map(item=><li key={item}>{item}</li>)}</ul></div>}<button className="underlink" onClick={()=>onOriginal(o.id)}>Vezi meniul original <ArrowUpRight size={17}/></button></details><button className="button dark-button full" onClick={()=>request(o)}>Solicită ofertă <ArrowUpRight size={18}/></button></article>)}</div>{group==='celebration'&&<p className="event-offer-note">Pentru aniversări și evenimente corporate, <a href={'mailto:'+business.email+'?subject=Solicitare%20ofert%C4%83%20eveniment'}>solicită o ofertă personalizată</a>.</p>}<p className="event-offer-note">Disponibilitatea datei și detaliile evenimentului se stabilesc cu Oana Poteca, Event Manager: <a href="tel:0761736599">0761 736 599</a>.</p>{quote&&<div className="event-quote" ref={quoteRef}><div><p className="eyebrow">PLANIFICĂM ÎMPREUNĂ</p><h3>{quote.title}<br/><em>{quote.subtitle}</em></h3><p>Completează detaliile și pregătește emailul către Oana Poteca. Cererea se trimite din aplicația ta de email.</p><a href="tel:0761736599"><Phone size={17}/>0761 736 599</a></div><form onSubmit={draft}><div className="form-grid"><label>Nume<input name="name" required minLength={2} maxLength={80} autoComplete="name"/></label><label>Telefon<input name="phone" type="tel" required pattern="\+?[0-9 ()-]{9,20}" autoComplete="tel"/></label><label>Data evenimentului<input name="date" type="date" min={new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Bucharest',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())} required/></label><label>Număr invitați<input name="guests" type="number" required min={1} step={1}/></label><label className="span-2">Observații<textarea name="notes" maxLength={1000} placeholder="Preferințe, opțiuni suplimentare, ce ai vrea să știm…"/></label></div><button className="button gold full" type="submit">Pregătește emailul <Mail size={18}/></button><a className="quote-mail-link" href={'mailto:'+business.email}>{business.email}</a></form></div>}</div>;
}

